drop policy if exists "travelers cancel own transfer requests" on public.driver_transfer_requests;
create or replace function public.respond_to_driver_transfer_request(p_request_id uuid,p_decision text) returns public.driver_transfer_requests language plpgsql security definer set search_path=public as $$ declare v_driver public.driver_profiles;v_request public.driver_transfer_requests;v_conflict boolean;begin if p_decision not in ('accepted','declined') then raise exception 'invalid_decision';end if;select * into v_driver from public.driver_profiles where user_id=auth.uid();if v_driver.id is null then raise exception 'driver_profile_required';end if;select * into v_request from public.driver_transfer_requests where id=p_request_id and driver_id=v_driver.id for update;if v_request.id is null then raise exception 'request_not_found';end if;if v_request.status<>'requested' then raise exception 'request_already_resolved';end if;if p_decision='accepted' then if v_driver.service_status<>'active' or v_driver.verification_state<>'verified' or v_driver.driving_license_compliance_status not in ('valid','expiring_soon') then raise exception 'driver_not_eligible';end if;select exists(select 1 from public.driver_availability a where a.driver_id=v_driver.id and a.available_on=v_request.requested_at::date and a.status='unavailable' and (a.start_time is null or a.start_time<=v_request.requested_at::time) and (a.end_time is null or a.end_time>v_request.requested_at::time)) into v_conflict;if v_conflict then raise exception 'driver_unavailable';end if;end if;update public.driver_transfer_requests set status=p_decision,updated_at=now() where id=v_request.id returning * into v_request;return v_request;end;$$;
revoke all on function public.respond_to_driver_transfer_request(uuid,text) from public;grant execute on function public.respond_to_driver_transfer_request(uuid,text) to authenticated;
create or replace function public.cancel_driver_transfer_request(p_request_id uuid) returns public.driver_transfer_requests language plpgsql security definer set search_path=public as $$ declare v_request public.driver_transfer_requests;begin select * into v_request from public.driver_transfer_requests where id=p_request_id and traveler_id=auth.uid() for update;if v_request.id is null then raise exception 'request_not_found';end if;if v_request.status<>'requested' then raise exception 'request_not_cancellable';end if;update public.driver_transfer_requests set status='cancelled',updated_at=now() where id=v_request.id returning * into v_request;return v_request;end;$$;
revoke all on function public.cancel_driver_transfer_request(uuid) from public;grant execute on function public.cancel_driver_transfer_request(uuid) to authenticated;
